@main

fn add(a int, b int) int {
    << a + b
}

struct Counter {
    n int
}

fn (c Counter) get() int {
    << c.n
}

fn (c &mut Counter) inc() {
    c.n += 1
}

fn main() int {
    println(add(40, 2))
    mut c := Counter{n: 10}
    println(c.get())
    c.inc()
    println(c.get())
    << 0
}
